/**
 * Converts a string to title case based on specific rules.
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') {
    return '';
  }

  const smallWords = new Set(['a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as']);

  // Split text into words and whitespace while preserving the structure
  // This regex matches sequences of non-whitespace characters (words)
  const parts = text.split(/(\s+)/);
  const words = parts.filter(part => !/^\s+$/.test(part) && part !== '');

  const processedWords = parts.map((part, index) => {
    // If it's whitespace, return as is
    if (/^\s+$/.test(part) || part === '') {
      return part;
    }

    // Find the index of this word among all non-whitespace words
    const wordIndex = parts.slice(0, index).filter(p => !/^\s+$/.test(p) && p !== '').length;
    const isFirst = wordIndex === 0;
    const isLast = wordIndex === words.length - 1;

    return processWord(part, isFirst, isLast, smallWords);
  });

  return processedWords.join('');
}

function processWord(word, isFirst, isLast, smallWords) {
  // Rule 2: Hyphenated words
  if (word.includes('-')) {
    return word.split('-').map(part => processWord(part, false, false, smallWords)).join('-');
  }

  // Rule 1: Acronyms
  if (/^[A-Z]{2,}$/.test(word)) {
    return word;
  }

  // Rule 4: Small words
  const lower = word.toLowerCase();
  if (smallWords.has(lower) && !isFirst && !isLast) {
    return lower;
  }

  // Rule 3: Capitalizing
  // Find the first letter a-z
  let result = lower.split('');
  for (let i = 0; i < result.length; i++) {
    if (/[a-z]/.test(result[i])) {
      result[i] = result[i].toUpperCase();
      break;
    }
  }
  return result.join('');
}
