/**
 * Parses a single line of CSV according to RFC 4180-like rules.
 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If the CSV format is invalid.
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const result = [];
  let i = 0;
  const len = line.length;

  // Handle empty input as a single empty field
  if (len === 0) return [""];

  while (i <= len) {
    if (i < len && line[i] === '"') {
      // Quoted field
      let field = "";
      i++; // Skip opening quote
      let closed = false;

      while (i < len) {
        if (line[i] === '"') {
          if (i + 1 < len && line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) {
        throw new RangeError('Quoted field not closed');
      }

      // After a closing quote, we must have a comma or end of string
      if (i < len && line[i] !== ',') {
        throw new RangeError('Invalid character after closing quote');
      }

      result.push(field);
      i++; // Skip comma
    } else {
      // Unquoted field
      let field = "";
      while (i < len && line[i] !== ',') {
        if (line[i] === '"') {
          throw new RangeError('Quote found in unquoted field');
        }
        field += line[i];
        i++;
      }
      result.push(field);
      i++; // Skip comma
    }

    // If the line ends with a comma, the loop continues and adds an empty string
    if (i > len) break;
  }

  return result;
}
