/**
 * Wraps text into lines of at most `width` characters.
 * 
 * @param {string} text 
 * @param {number} width 
 * @returns {string[]}
 */
export function wrapText(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('Text must be a string.');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new RangeError('Width must be an integer of at least 1.');
  }

  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) {
    return [];
  }

  const result = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    if (word.length > width) {
      // Finish current line if it exists
      if (currentLine.length > 0) {
        result.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }

      // Break the long word into pieces of `width`
      for (let i = 0; i < word.length; i += width) {
        const piece = word.slice(i, i + width);
        if (piece.length === width) {
          result.push(piece);
        } else {
          // Last piece becomes the start of the next line
          currentLine = [piece];
          currentLength = piece.length;
        }
      }
    } else {
      // Check if word fits in current line
      // Need: currentLength + (1 space if not empty) + word.length <= width
      const spaceNeeded = currentLine.length > 0 ? 1 : 0;
      if (currentLength + spaceNeeded + word.length <= width) {
        currentLine.push(word);
        currentLength += spaceNeeded + word.length;
      } else {
        // Start new line
        result.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      }
    }
  }

  if (currentLine.length > 0) {
    result.push(currentLine.join(' '));
  }

  return result;
}
