/**
 * LruCache implementation using a Map.
 * In JavaScript, Map objects maintain insertion order.
 * By deleting and re-inserting a key, we can move it to the "most recent" 
 * position (the end of the Map iteration order).
 */
export class LruCache {
  #capacity;
  #cache;

  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("Capacity must be an integer of at least 1.");
    }
    this.#capacity = capacity;
    this.#cache = new Map();
  }

  get(key) {
    if (!this.#cache.has(key)) {
      return undefined;
    }
    // Refresh the key by re-inserting it
    const value = this.#cache.get(key);
    this.#cache.delete(key);
    this.#cache.set(key, value);
    return value;
  }

  set(key, value) {
    if (this.#cache.has(key)) {
      // Update existing key: remove to re-insert at the end
      this.#cache.delete(key);
    } else if (this.#cache.size >= this.#capacity) {
      // Evict the least recently used (the first item in the Map)
      const firstKey = this.#cache.keys().next().value;
      this.#cache.delete(firstKey);
    }
    this.#cache.set(key, value);
    return this;
  }

  has(key) {
    return this.#cache.has(key);
  }

  delete(key) {
    return this.#cache.delete(key);
  }

  get size() {
    return this.#cache.size;
  }

  keys() {
    // Map.prototype.keys() returns keys in insertion order (LRU to MRU)
    return Array.from(this.#cache.keys());
  }
}
