/**
 * Formats a byte count into a human-readable string.
 * 
 * @param {number} bytes 
 * @param {Object} [options]
 * @param {boolean} [options.binary=false]
 * @param {number} [options.decimals=1]
 * @returns {string}
 */
export function formatBytes(bytes, options = {}) {
  const { binary = false, decimals = 1 } = options;

  // Validation
  if (typeof bytes !== 'number') {
    throw new TypeError('bytes must be a number');
  }
  if (!Number.isFinite(bytes) || bytes < 0) {
    throw new RangeError('bytes must be a non-negative finite number');
  }
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 3) {
    throw new RangeError('decimals must be an integer between 0 and 3');
  }

  const base = binary ? 1024 : 1000;
  const units = binary
    ? ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB']
    : ['B', 'kB', 'MB', 'GB', 'TB', 'PB'];

  // Rule: Below one unit, show as whole number
  if (bytes < base) {
    return `${Math.round(bytes)} B`;
  }

  let unitIndex = 0;
  let value = bytes;

  // Divide until we find the appropriate unit
  while (value >= base && unitIndex < units.length - 1) {
    value /= base;
    unitIndex++;
  }

  // Rounding logic:
  // We need to round to 'decimals' places.
  // Using a multiplier 10^decimals to handle rounding.
  const multiplier = Math.pow(10, decimals);
  value = Math.round(value * multiplier) / multiplier;

  // Rule: If rounding makes the number equal to the base, move up one unit
  if (value >= base && unitIndex < units.length - 1) {
    value /= base;
    unitIndex++;
  }

  // Format the string
  // toFixed(decimals) handles the trailing zeros requirement
  const formattedValue = decimals === 0 
    ? Math.round(value).toString() 
    : value.toFixed(decimals);

  return `${formattedValue} ${units[unitIndex]}`;
}
