/**
 * Groups items of an array into a Map based on a key (string or function).
 * 
 * @param {Array} items - The array to group.
 * @param {string|Function} key - The property name or function to determine the group.
 * @returns {Map} - A Map where keys are group identifiers and values are arrays of items.
 * @throws {TypeError} - If items is not an array or key is not a string/function.
 */
export function groupBy(items, key) {
  if (!Array.isArray(items)) {
    throw new TypeError("The first argument must be an array.");
  }

  const isKeyFunction = typeof key === 'function';
  const isKeyString = typeof key === 'string';

  if (!isKeyFunction && !isKeyString) {
    throw new TypeError("The key must be a string or a function.");
  }

  const result = new Map();

  items.forEach((item, index) => {
    let groupKey;

    if (isKeyFunction) {
      groupKey = key(item, index);
    } else {
      // If item is null or undefined, the property access should result in undefined
      if (item === null || item === undefined) {
        groupKey = undefined;
      } else {
        groupKey = item[key];
      }
    }

    if (!result.has(groupKey)) {
      result.set(groupKey, []);
    }

    result.get(groupKey).push(item);
  });

  return result;
}
