/**
 * Converts a string to title case based on specific rules.
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') return '';

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  // Split by whitespace but keep the whitespace structure
  // We use a regex that captures the whitespace as well
  const parts = text.split(/(\s+)/);

  const words = parts.map((part, index) => {
    // If it's whitespace, return as is
    if (/^\s+$/.test(part)) return part;

    // Rule 2: Handle hyphenated words
    if (part.includes('-')) {
      return part.split('-').map(subPart => processWord(subPart, false)).join('-');
    }

    // Determine if it's the first or last word (ignoring whitespace)
    const nonWhitespace = parts.filter(p => !/^\s+$/.test(p));
    const isFirst = part === nonWhitespace[0];
    const isLast = part === nonWhitespace[nonWhitespace.length - 1];

    return processWord(part, isFirst || isLast, isFirst || isLast, smallWords);
  });

  return words.join('');
}

function processWord(word, isFirstOrLast, forceCapitalize = false, smallWords = null) {
  // Rule 1: Acronyms (A-Z only, length >= 2)
  if (/^[A-Z]{2,}$/.test(word)) {
    return word;
  }

  // Rule 4: Small words
  const lower = word.toLowerCase();
  if (smallWords && smallWords.has(lower) && !isFirstOrLast) {
    return lower;
  }

  // Rule 3: Capitalizing
  // Find the first letter (a-z)
  const chars = word.split('');
  let found = false;
  const result = chars.map(char => {
    if (!found && /[a-z]/i.test(char)) {
      found = true;
      return char.toUpperCase();
    }
    return char.toLowerCase();
  }).join('');

  return result;
}
