/**
 * Formats a byte count into a human-readable string.
 * 
 * @param {number} bytes 
 * @param {Object} [options] 
 * @param {boolean} [options.binary=false] 
 * @param {number} [options.decimals=1] 
 * @returns {string}
 */
export function formatBytes(bytes, options = {}) {
  const { binary = false, decimals = 1 } = options;

  // Validation
  if (typeof bytes !== 'number') {
    throw new TypeError('Bytes must be a number.');
  }
  if (!Number.isFinite(bytes) || bytes < 0) {
    throw new RangeError('Bytes must be a non-negative finite number.');
  }
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 3) {
    throw new RangeError('Decimals must be an integer between 0 and 3.');
  }

  const base = binary ? 1024 : 1000;
  const units = binary 
    ? ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'] 
    : ['B', 'kB', 'MB', 'GB', 'TB', 'PB'];

  // Rule: Below base, show as whole number
  if (bytes < base) {
    return `${Math.round(bytes)} B`;
  }

  let unitIndex = 0;
  let value = bytes;

  // Find the appropriate unit
  while (value >= base && unitIndex < units.length - 1) {
    value /= base;
    unitIndex++;
  }

  // Rounding logic
  // We use toFixed to handle the decimal precision, then check if it hit the base
  const factor = Math.pow(10, decimals);
  let roundedValue = Math.round(value * factor) / factor;

  // Check if rounding pushed us to the base (e.g., 999.95 -> 1000.0)
  // Only move up if we aren't at the max unit (PB/PiB)
  if (roundedValue >= base && unitIndex < units.length - 1) {
    roundedValue /= base;
    unitIndex++;
  }

  // Format the string
  const formattedNumber = roundedValue.toFixed(decimals);

  return `${formattedNumber} ${units[unitIndex]}`;
}
