/**
 * Roman numerals, strictly.
 */

const MAPPING = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I']
];

/**
 * Converts an integer from 1 to 3999 to its Roman numeral.
 * @param {number} n 
 * @returns {string}
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number.');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999.');
  }

  let result = '';
  let remaining = n;

  for (const [value, symbol] of MAPPING) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }

  return result;
}

/**
 * Converts a Roman numeral back to a number, strictly.
 * @param {string} text 
 * @returns {number}
 */
export function fromRoman(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string.');
  }

  // The regex ensures the string is exactly the canonical form
  // M{0,3} matches 0-3000
  // (CM|CD|D?C{0,3}) matches 900, 400, 500-800, 100-300
  // (XC|XL|L?X{0,3}) matches 90, 40, 50-80, 10-30
  // (IX|IV|V?I{0,3}) matches 9, 4, 5-8, 1-3
  const canonicalRegex = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

  if (text === '' || !canonicalRegex.test(text)) {
    throw new RangeError('Input is not a valid canonical Roman numeral.');
  }

  // Verify that the generated canonical form matches the input exactly
  // This handles cases like empty strings or invalid combinations that might pass regex
  let n = 0;
  let remaining = text;

  for (const [value, symbol] of MAPPING) {
    while (remaining.startsWith(symbol)) {
      n += value;
      remaining = remaining.slice(symbol.length);
    }
  }

  if (remaining !== '' || n < 1 || n > 3999) {
    throw new RangeError('Input is not a valid canonical Roman numeral.');
  }

  return n;
}
