/**
 * Roman numerals, strictly
 * 
 * Canonical mapping for Roman numerals 1-3999.
 */

const ROMAN_MAP = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I']
];

/**
 * Converts an integer from 1 to 3999 to its canonical Roman numeral.
 * @param {number} n 
 * @returns {string}
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number.');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999.');
  }

  let result = '';
  let remaining = n;

  for (const [value, symbol] of ROMAN_MAP) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }

  return result;
}

/**
 * Converts a canonical Roman numeral string back to an integer.
 * @param {string} text 
 * @returns {number}
 */
export function fromRoman(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string.');
  }

  if (text.length === 0) {
    throw new RangeError('Input string cannot be empty.');
  }

  // Validate that the input is exactly the canonical form
  // We can do this by checking if toRoman(n) === text for some n.
  // Since the mapping is bijective for 1-3999, we can reverse the process
  // and verify the result.

  let result = 0;
  let remaining = text;
  let i = 0;

  while (i < ROMAN_MAP.length && remaining.length > 0) {
    const [value, symbol] = ROMAN_MAP[i];
    while (remaining.startsWith(symbol)) {
      result += value;
      remaining = remaining.slice(symbol.length);
    }
    i++;
  }

  // If there is leftover text or the result is invalid, it wasn't a canonical form
  if (remaining.length > 0 || result === 0 || toRoman(result) !== text) {
    throw new RangeError('Input is not a valid canonical Roman numeral.');
  }

  return result;
}
