/**
 * Parses a single line of CSV.
 * 
 * @param {string} line 
 * @returns {string[]}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If the CSV format is invalid.
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const fields = [];
  let i = 0;

  while (i <= line.length) {
    if (i < line.length && line[i] === '"') {
      // Quoted field
      let field = '';
      i++; // Skip opening quote
      let closed = false;

      while (i < line.length) {
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) {
        throw new RangeError('Quoted field not closed');
      }

      // After closing quote, must be comma or end of line
      if (i < line.length && line[i] !== ',') {
        throw new RangeError('Invalid character after closing quote');
      }

      fields.push(field);
      i++; // Skip comma
    } else {
      // Unquoted field
      let field = '';
      while (i < line.length && line[i] !== ',') {
        if (line[i] === '"') {
          throw new RangeError('Quote found in unquoted field');
        }
        field += line[i];
        i++;
      }
      fields.push(field);
      i++; // Skip comma
    }

    // Handle trailing comma case: if line ends with ',', 
    // the loop logic above will increment i past length, 
    // but we need to ensure an empty field is added.
    if (i === line.length + 1 && line.endsWith(',')) {
      fields.push('');
      break;
    }
  }

  return fields;
}
