/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If input is invalid or contains duplicate units.
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input cannot be empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  // Regex breakdown:
  // ^\s* : Start of string
  // (\d+(?:\.\d+)?) : Number (digits, optional dot + digits)
  // (ms|s|m|h|d|w) : Unit
  // \s* : Optional whitespace
  // Global flag to find all components
  const componentRegex = /(\d+(?:\.\d+)?)(ms|s|m|h|d|w)/g;

  const matches = [...trimmed.matchAll(componentRegex)];

  // Validate that the entire string was consumed by the regex
  // We remove all valid components and whitespace; if anything remains, it's invalid
  let remaining = trimmed;
  for (const match of matches) {
    remaining = remaining.replace(match[0], '');
  }
  if (remaining.trim() !== '') {
    throw new RangeError('Invalid format');
  }

  let totalMs = 0;
  const seenUnits = new Set();

  for (const match of matches) {
    const valueStr = match[1];
    const unit = match[2];

    // Validate number format (no leading/trailing dots)
    if (valueStr.startsWith('.') || valueStr.endsWith('.')) {
      throw new RangeError('Invalid number format');
    }

    if (seenUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }
    seenUnits.add(unit);

    const value = parseFloat(valueStr);
    totalMs += value * units[unit];
  }

  return Math.round(totalMs);
}
