/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If input is invalid or has repeated units.
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input cannot be empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  // Regex breakdown:
  // ^\s* : Start of string
  // (\d+(?:\.\d+)?) : Number (digits, optional decimal point with digits)
  // ([a-z]+) : Unit
  // \s* : Optional whitespace
  // g : Global to find all components
  const regex = /(\d+(?:\.\d+)?)([a-z]+)/g;
  const matches = [...trimmed.matchAll(regex)];

  // Validate that the entire string was consumed by the regex
  // We reconstruct the string from matches to ensure no invalid characters exist
  let reconstructed = "";
  for (const match of matches) {
    reconstructed += match[0];
  }
  if (reconstructed.replace(/\s/g, '') !== trimmed.replace(/\s/g, '')) {
    throw new RangeError('Invalid format');
  }

  let totalMs = 0;
  const seenUnits = new Set();

  for (const match of matches) {
    const value = parseFloat(match[1]);
    const unit = match[2];

    if (!units.hasOwnProperty(unit)) {
      throw new RangeError(`Unknown unit: ${unit}`);
    }

    if (seenUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    seenUnits.add(unit);
    totalMs += value * units[unit];
  }

  return Math.round(totalMs);
}
