/**
 * Parses a single line of CSV into an array of strings.
 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} if input is not a string
 * @throws {RangeError} if the CSV format is malformed
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const result = [];
  let i = 0;

  while (i <= line.length) {
    if (i < line.length && line[i] === '"') {
      // Quoted field
      let field = '';
      i++; // Skip opening quote
      let closed = false;

      while (i < line.length) {
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) {
        throw new RangeError('Quoted field not closed');
      }

      // Check for trailing characters after closing quote
      if (i < line.length && line[i] !== ',') {
        throw new RangeError('Malformed CSV: characters found after closing quote');
      }

      result.push(field);
    } else {
      // Unquoted field
      let field = '';
      while (i < line.length && line[i] !== ',') {
        if (line[i] === '"') {
          throw new RangeError('Malformed CSV: quote inside unquoted field');
        }
        field += line[i];
        i++;
      }
      result.push(field);
    }

    // If we are at a comma, skip it and continue to the next field
    if (i < line.length && line[i] === ',') {
      i++;
      // If the line ends with a comma, the loop will run one more time
      // to capture the empty field after the last comma.
      if (i === line.length) {
        result.push('');
      }
    } else {
      break;
    }
  }

  return result;
}
