/**
 * Parses a URL query string into an object.
 * 
 * @param {string} query
 * @returns {Object}
 */
export function parseQuery(query) {
  if (typeof query !== 'string') {
    throw new TypeError('Query must be a string');
  }

  const result = Object.create(null);
  const rawQuery = query.startsWith('?') ? query.slice(1) : query;

  if (!rawQuery) {
    return result;
  }

  const pairs = rawQuery.split('&');

  for (const pair of pairs) {
    if (pair === '') continue;

    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;

    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.slice(0, eqIndex);
      rawValue = pair.slice(eqIndex + 1);
    }

    const key = decode(rawKey);
    const value = decode(rawValue);

    const isArrayKey = key.endsWith('[]');
    const finalKey = isArrayKey ? key.slice(0, -2) : key;

    if (isArrayKey) {
      if (!(finalKey in result) || !Array.isArray(result[finalKey])) {
        const existing = finalKey in result ? [result[finalKey]] : [];
        result[finalKey] = existing;
      }
      result[finalKey].push(value);
    } else {
      if (finalKey in result) {
        if (Array.isArray(result[finalKey])) {
          result[finalKey].push(value);
        } else {
          result[finalKey] = [result[finalKey], value];
        }
      } else {
        result[finalKey] = value;
      }
    }
  }

  return result;
}

/**
 * Decodes a query component.
 * Replaces '+' with ' ' and decodes percent-escapes.
 */
function decode(str) {
  const replaced = str.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(replaced);
  } catch (e) {
    throw new RangeError('Malformed percent-escape');
  }
}
