/**
 * Turns text into a lowercase, URL-safe slug.
 * 
 * @param {string} text 
 * @param {Object} [options]
 * @param {number} [options.maxLength]
 * @returns {string}
 */
export function slugify(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (options.maxLength !== undefined) {
    if (!Number.isInteger(options.maxLength) || options.maxLength <= 0) {
      throw new RangeError('maxLength must be a positive integer');
    }
  }

  // 1. Normalize Unicode NFKD and remove combining marks (U+0300 to U+036F)
  let slug = text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');

  // 2. Lowercase
  slug = slug.toLowerCase();

  // 3. Replace non-alphanumeric characters with a single hyphen
  // 4. Remove leading/trailing hyphens
  slug = slug
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  // 6. Handle maxLength
  if (options.maxLength !== undefined && slug.length > options.maxLength) {
    slug = slug.substring(0, options.maxLength);
    // Remove trailing hyphens again after cutting
    slug = slug.replace(/-+$/g, '');
  }

  return slug;
}
