/**
 * Converts text to title case based on specific rules.
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') {
    return '';
  }

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  // Split text while preserving whitespace
  const parts = text.split(/(\s+)/);

  // Identify words (non-whitespace parts)
  const wordIndices = [];
  for (let i = 0; i < parts.length; i++) {
    if (parts[i].trim().length > 0) {
      wordIndices.push(i);
    }
  }

  if (wordIndices.length === 0) return text;

  const firstIdx = wordIndices[0];
  const lastIdx = wordIndices[wordIndices.length - 1];

  function processWord(word, isFirstOrLast) {
    // 1. Acronyms
    if (/^[A-Z]{2,}$/.test(word)) {
      return word;
    }

    // 2. Hyphenated words
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false)).join('-');
    }

    // 3 & 4. Small words and Capitalizing
    const lower = word.toLowerCase();
    if (!isFirstOrLast && smallWords.has(lower)) {
      return lower;
    }

    // Capitalize first letter (a-z)
    return word.replace(/([a-z])/, (match) => match.toUpperCase());
  }

  // Process each word part
  for (let i = 0; i < parts.length; i++) {
    if (wordIndices.includes(i)) {
      const isFirstOrLast = (i === firstIdx || i === lastIdx);
      parts[i] = processWord(parts[i], isFirstOrLast);
    }
  }

  return parts.join('');
}
