/**
 * Compares two semantic version strings.
 * 
 * @param {string} a 
 * @param {string} b 
 * @returns {-1 | 0 | 1}
 */
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    throw new TypeError("Arguments must be strings");
  }

  const parse = (v) => {
    const regex = /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
    const match = v.match(regex);

    if (!match) throw new RangeError("Invalid semantic version");

    const [_, major, minor, patch, prerelease, build] = match;

    // Validate leading zeros for numeric parts
    if ((major.length > 1 && major[0] === '0') ||
        (minor.length > 1 && minor[0] === '0') ||
        (patch.length > 1 && patch[0] === '0')) {
      throw new RangeError("Invalid semantic version: leading zeros");
    }

    const validateIdentifiers = (str) => {
      if (!str) return [];
      const parts = str.split('.');
      for (const part of parts) {
        if (part === "") throw new RangeError("Empty identifier");
        // Check for numeric identifiers with leading zeros
        if (/^\d+$/.test(part) && part.length > 1 && part[0] === '0') {
          throw new RangeError("Numeric identifier has leading zero");
        }
      }
      return parts;
    };

    return {
      major: parseInt(major, 10),
      minor: parseInt(minor, 10),
      patch: parseInt(patch, 10),
      prerelease: prerelease ? validateIdentifiers(prerelease) : null
    };
  };

  const v1 = parse(a);
  const v2 = parse(b);

  // 1. Compare Major, Minor, Patch
  if (v1.major !== v2.major) return v1.major > v2.major ? 1 : -1;
  if (v1.minor !== v2.minor) return v1.minor > v2.minor ? 1 : -1;
  if (v1.patch !== v2.patch) return v1.patch > v2.patch ? 1 : -1;

  // 2. Compare Prerelease
  if (v1.prerelease === null && v2.prerelease !== null) return 1;
  if (v1.prerelease !== null && v2.prerelease === null) return -1;
  if (v1.prerelease !== null && v2.prerelease !== null) {
    const len = Math.min(v1.prerelease.length, v2.prerelease.length);
    for (let i = 0; i < len; i++) {
      const p1 = v1.prerelease[i];
      const p2 = v2.prerelease[i];
      const isP1Num = /^\d+$/.test(p1);
      const isP2Num = /^\d+$/.test(p2);

      if (isP1Num && isP2Num) {
        const n1 = parseInt(p1, 10);
        const n2 = parseInt(p2, 10);
        if (n1 !== n2) return n1 > n2 ? 1 : -1;
      } else if (!isP1Num && !isP2Num) {
        if (p1 !== p2) return p1 > p2 ? 1 : -1;
      } else {
        return isP1Num ? -1 : 1;
      }
    }
    if (v1.prerelease.length !== v2.prerelease.length) {
      return v1.prerelease.length > v2.prerelease.length ? 1 : -1;
    }
  }

  return 0;
