/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If input is invalid or contains duplicate units.
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input cannot be empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  // Regex breakdown:
  // ^\s* : Start of string
  // (\d+(?:\.\d+)?) : Number (digits, optional dot + digits)
  // ([a-z]+) : Unit
  // \s* : Whitespace between components
  // Global flag to find all components
  const componentRegex = /(\d+(?:\.\d+)?)([a-z]+)/g;

  // Validate that the entire string is composed of valid components and whitespace
  // We check this by ensuring the regex matches the entire string length
  let totalMs = 0;
  const foundUnits = new Set();
  let matchCount = 0;
  let lastIndex = 0;

  const matches = [...trimmed.matchAll(componentRegex)];

  // Check if the concatenation of matches covers the whole string (ignoring whitespace)
  let reconstructed = "";
  for (const match of matches) {
    reconstructed += match[0];
    const val = parseFloat(match[1]);
    const unit = match[2];

    if (!units.hasOwnProperty(unit)) {
      throw new RangeError(`Invalid unit: ${unit}`);
    }
    if (foundUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    foundUnits.add(unit);
    totalMs += val * units[unit];
    matchCount++;
  }

  // Ensure no invalid characters or gaps exist
  // Remove all whitespace and compare to the reconstructed string of matches
  if (trimmed.replace(/\s+/g, '') !== reconstructed) {
    throw new RangeError('Invalid format');
  }

  if (matchCount === 0) {
    throw new RangeError('No valid components found');
  }

  return Math.round(totalMs);
}
