/**
 * Roman numerals conversion utility.
 */

const ROMAN_MAP = [
  { val: 1000, sym: 'M' },
  { val: 900, sym: 'CM' },
  { val: 500, sym: 'D' },
  { val: 400, sym: 'CD' },
  { val: 100, sym: 'C' },
  { val: 90, sym: 'XC' },
  { val: 50, sym: 'L' },
  { val: 40, sym: 'XL' },
  { val: 10, sym: 'X' },
  { val: 9, sym: 'IX' },
  { val: 5, sym: 'V' },
  { val: 4, sym: 'IV' },
  { val: 1, sym: 'I' }
];

/**
 * Converts an integer from 1 to 3999 to its canonical Roman numeral.
 * @param {number} n 
 * @returns {string}
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number.');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999.');
  }

  let result = '';
  let remaining = n;

  for (const { val, sym } of ROMAN_MAP) {
    while (remaining >= val) {
      result += sym;
      remaining -= val;
    }
  }

  return result;
}

/**
 * Converts a canonical Roman numeral string back to an integer.
 * @param {string} text 
 * @returns {number}
 */
export function fromRoman(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string.');
  }

  // Check if the string is empty or contains invalid characters
  if (text.length === 0 || /[^IVXLCDM]/.test(text)) {
    throw new RangeError('Invalid Roman numeral.');
  }

  // The strict requirement: fromRoman(toRoman(n)) === n
  // We can verify this by converting the input string back to a number
  // and then converting that number back to a Roman string to compare.

  let num = 0;
  let remaining = text;

  for (const { val, sym } of ROMAN_MAP) {
    while (remaining.startsWith(sym)) {
      num += val;
      remaining = remaining.slice(sym.length);
    }
  }

  // If there's leftover text, it wasn't a canonical Roman numeral
  if (remaining.length > 0) {
    throw new RangeError('Invalid Roman numeral.');
  }

  // Verify canonical form by re-encoding
  if (toRoman(num) !== text) {
    throw new RangeError('Invalid Roman numeral.');
  }

  return num;
}
