/**
 * Compares two semantic version strings.
 * 
 * @param {string} a 
 * @param {string} b 
 * @returns {-1 | 0 | 1}
 */
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    throw new TypeError("Arguments must be strings");
  }

  const parse = (v) => {
    const regex = /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
    const match = v.match(regex);

    if (!match) throw new RangeError("Invalid semantic version");

    const [, major, minor, patch, prerelease, build] = match;

    // Validate non-leading zeros for numeric parts
    const checkLeadingZero = (s) => s.length > 1 && s.startsWith('0');
    if (checkLeadingZero(major) || checkLeadingZero(minor) || checkLeadingZero(patch)) {
      throw new RangeError("Invalid semantic version: leading zeros");
    }

    return {
      major: parseInt(major, 10),
      minor: parseInt(minor, 10),
      patch: parseInt(patch, 10),
      prerelease: prerelease ? prerelease.split('.') : null
    };
  };

  const v1 = parse(a);
  const v2 = parse(b);

  // 1. Compare MAJOR, MINOR, PATCH
  if (v1.major !== v2.major) return v1.major > v2.major ? 1 : -1;
  if (v1.minor !== v2.minor) return v1.minor > v2.minor ? 1 : -1;
  if (v1.patch !== v2.patch) return v1.patch > v2.patch ? 1 : -1;

  // 2. Prerelease precedence
  if (v1.prerelease && !v2.prerelease) return -1;
  if (!v1.prerelease && v2.prerelease) return 1;
  if (!v1.prerelease && !v2.prerelease) return 0;

  // 3. Compare prerelease identifiers
  const p1 = v1.prerelease;
  const p2 = v2.prerelease;
  const len = Math.max(p1.length, p2.length);

  for (let i = 0; i < len; i++) {
    if (p1[i] === undefined) return -1;
    if (p2[i] === undefined) return 1;

    const isNum1 = /^\d+$/.test(p1[i]);
    const isNum2 = /^\d+$/.test(p2[i]);

    if (isNum1 && isNum2) {
      const n1 = parseInt(p1[i], 10);
      const n2 = parseInt(p2[i], 10);
      if (n1 !== n2) return n1 > n2 ? 1 : -1;
    } else if (!isNum1 && !isNum2) {
      if (p1[i] !== p2[i]) return p1[i] > p2[i] ? 1 : -1;
    } else {
      // Numeric is lower than alphanumeric
      return isNum1 ? -1 : 1;
    }
  }

  return 0;
}
