/**
 * LruCache implementation using a Map.
 * In JavaScript, Map objects maintain insertion order.
 * By deleting and re-inserting a key, we can move it to the "most recent" 
 * position (the end of the map).
 */
export class LruCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("Capacity must be an integer of at least 1.");
    }
    this._capacity = capacity;
    this._cache = new Map();
  }

  get(key) {
    if (!this._cache.has(key)) {
      return undefined;
    }
    // Refresh position: delete and re-insert
    const value = this._cache.get(key);
    this._cache.delete(key);
    this._cache.set(key, value);
    return value;
  }

  set(key, value) {
    if (this._cache.has(key)) {
      // Update existing: move to end
      this._cache.delete(key);
    } else if (this._cache.size >= this._capacity) {
      // Evict least recently used (the first item in the Map)
      const firstKey = this._cache.keys().next().value;
      this._cache.delete(firstKey);
    }
    this._cache.set(key, value);
    return this;
  }

  has(key) {
    return this._cache.has(key);
  }

  delete(key) {
    return this._cache.delete(key);
  }

  get size() {
    return this._cache.size;
  }

  keys() {
    return Array.from(this._cache.keys());
  }
}
