/**
 * Flattens nested arrays down to a specified depth.
 * @param {Array} items 
 * @param {number} depth 
 * @returns {Array}
 */
export function flatten(items, depth = 1) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }

  // Validate depth: must be non-negative integer or Infinity
  const isInfinity = depth === Infinity;
  const isNonNegativeInt = typeof depth === 'number' && Number.isInteger(depth) && depth >= 0;

  if (!isInfinity && !isNonNegativeInt) {
    throw new RangeError('depth must be a non-negative integer or Infinity');
  }

  const flattenRecursive = (arr, currentDepth) => {
    let result = [];
    for (const item of arr) {
      if (currentDepth > 0 && Array.isArray(item)) {
        result.push(...flattenRecursive(item, currentDepth - 1));
      } else {
        result.push(item);
      }
    }
    return result;
  };

  // If depth is Infinity, we can use a large number or handle it specifically
  const effectiveDepth = isInfinity ? Infinity : depth;
  return flattenRecursive(items, effectiveDepth);
}
