    if (!pair) continue;

    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;

    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.slice(0, eqIndex);
      rawValue = pair.slice(eqIndex + 1);
    }

    const key = decode(rawKey);
    const value = decode(rawValue);

    let finalKey = key;
    let forceArray = false;

    if (key.endsWith('[]')) {
      finalKey = key.slice(0, -2);
      forceArray = true;
    }

    if (forceArray) {
      isArrayKey[finalKey] = true;
    }

    if (finalKey in result) {
      if (Array.isArray(result[finalKey])) {
        result[finalKey].push(value);
      } else {
        result[finalKey] = [result[finalKey], value];
      }
    } else {
      if (forceArray) {
        result[finalKey] = [value];
      } else {
        result[finalKey] = value;
      }
    }
  }

  // Ensure keys marked as [] are always arrays, even if they only appeared once
  for (const key in isArrayKey) {
    if (!Array.isArray(result[key])) {
      result[key] = [result[key]];
    }
  }

  return result;
}

/**
 * Decodes a string by replacing '+' with space and decoding URI components.
 * Throws RangeError if URI decoding fails.
 */
function decode(str) {
  const replaced = str.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(replaced);
  } catch (e) {
    throw new RangeError('Malformed percent-escape');
  }
}
