/**
 * Groups items of an array into a Map based on a key.
 * 
 * @param {Array} items - The array of items to group.
 * @param {string|Function} key - The property name or a function to determine the group key.
 * @returns {Map} A Map where keys are the group identifiers and values are arrays of items.
 * @throws {TypeError} If items is not an array or key is not a string/function.
 */
export function groupBy(items, key) {
  if (!Array.isArray(items)) {
    throw new TypeError("The first argument must be an array.");
  }

  const isKeyFunction = typeof key === 'function';
  const isKeyString = typeof key === 'string';

  if (!isKeyFunction && !isKeyString) {
    throw new TypeError("The key must be a string or a function.");
  }

  const map = new Map();

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    let groupKey;

    if (isKeyFunction) {
      groupKey = key(item, i);
    } else {
      // If item is null/undefined, accessing property results in undefined
      if (item === null || item === undefined) {
        groupKey = undefined;
      } else {
        groupKey = item[key];
      }
    }

    if (!map.has(groupKey)) {
      map.set(groupKey, []);
    }

    map.get(groupKey).push(item);
  }

  return map;
}
