/**
 * Compares two semantic version strings.
 * 
 * @param {string} a 
 * @param {string} b 
 * @returns {-1 | 0 | 1}
 */
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    throw new TypeError('Arguments must be strings');
  }

  const parse = (v) => {
    const regex = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
    const match = v.match(regex);
    if (!match) throw new RangeError('Invalid semver string');

    const [_, major, minor, patch, prerelease, build] = match;

    const preParts = prerelease ? prerelease.split('.').map(part => {
      // Check if numeric: digits only, no leading zeros (unless it's just "0")
      if (/^(0|[1-9]\d*)$/.test(part)) {
        return { type: 'numeric', value: parseInt(part, 10) };
      }
      return { type: 'alphanumeric', value: part };
    }) : null;

    return {
      major: parseInt(major, 10),
      minor: parseInt(minor, 10),
      patch: parseInt(patch, 10),
      pre: preParts
    };
  };

  const v1 = parse(a);
  const v2 = parse(b);

  // 1. Compare Major, Minor, Patch
  if (v1.major !== v2.major) return v1.major > v2.major ? 1 : -1;
  if (v1.minor !== v2.minor) return v1.minor > v2.minor ? 1 : -1;
  if (v1.patch !== v2.patch) return v1.patch > v2.patch ? 1 : -1;

  // 2. Prerelease precedence
  if (v1.pre && !v2.pre) return -1;
  if (!v1.pre && v2.pre) return 1;
  if (!v1.pre && !v2.pre) return 0;

  // 3. Compare prerelease identifiers
  const len = Math.min(v1.pre.length, v2.pre.length);
  for (let i = 0; i < len; i++) {
    const p1 = v1.pre[i];
    const p2 = v2.pre[i];

    if (p1.type === 'numeric' && p2.type === 'numeric') {
      if (p1.value !== p2.value) return p1.value > p2.value ? 1 : -1;
    } else if (p1.type === 'numeric' && p2.type === 'alphanumeric') {
      return -1;
    } else if (p1.type === 'alphanumeric' && p2.type === 'numeric') {
      return 1;
    } else {
      // Both alphanumeric
      if (p1.value !== p2.value) return p1.value > p2.value ? 1 : -1;
    }
  }

  // If all shared identifiers are equal, the one with more identifiers is higher
  if (v1.pre.length !== v2.pre.length) {
    return v1.pre.length > v2.pre.length ? 1 : -1;
  }

  return 0;
}
