/**
 * Parses a single line of CSV according to RFC 4180-like rules.
 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If the CSV format is malformed.
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const result = [];
  let i = 0;
  const len = line.length;

  // Handle empty string case
  if (len === 0) return [""];

  while (i <= len) {
    if (i < len && line[i] === '"') {
      // Quoted field
      let field = "";
      i++; // Skip opening quote
      let closed = false;

      while (i < len) {
        if (line[i] === '"') {
          if (i + 1 < len && line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) throw new RangeError('Unclosed quoted field');

      // After a closing quote, we must see a comma or end of string
      if (i < len && line[i] !== ',') {
        throw new RangeError('Malformed CSV: character after closing quote');
      }

      result.push(field);
      i++; // Skip comma
    } else {
      // Unquoted field
      let start = i;
      let end = line.indexOf(',', i);
      if (end === -1) end = len;

      let field = line.substring(start, end);

      // Check for illegal quotes in unquoted field
      if (field.includes('"')) {
        throw new RangeError('Malformed CSV: quote in unquoted field');
      }

      result.push(field);
      i = end + 1;
    }

    // Handle trailing comma (e.g., "a," -> ["a", ""])
    if (i === len && line[len - 1] === ',') {
      result.push("");
      break;
    }
  }

  return result;
}
