/**
 * Roman numerals, strictly
 */

const ROMAN_MAP = [
  { val: 1000, sym: 'M' },
  { val: 900, sym: 'CM' },
  { val: 500, sym: 'D' },
  { val: 400, sym: 'CD' },
  { val: 100, sym: 'C' },
  { val: 90, sym: 'XC' },
  { val: 50, sym: 'L' },
  { val: 40, sym: 'XL' },
  { val: 10, sym: 'X' },
  { val: 9, sym: 'IX' },
  { val: 5, sym: 'V' },
  { val: 4, sym: 'IV' },
  { val: 1, sym: 'I' }
];

/**
 * Converts an integer from 1 to 3999 to its canonical Roman numeral.
 * @param {number} n 
 * @returns {string}
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number.');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999.');
  }

  let result = '';
  let remaining = n;

  for (const { val, sym } of ROMAN_MAP) {
    while (remaining >= val) {
      result += sym;
      remaining -= val;
    }
  }

  return result;
