  // This implies that if we convert the string back to a number,
  // then convert that number back to a Roman string, it must match the input.

  // Regex to validate basic Roman numeral structure (optional but helps performance)
  // This validates the characters and the general order, but the round-trip
  // check is the definitive test for "canonical" form.
  if (!/^[IVXLCDM]+$/.test(text)) {
    throw new RangeError('Invalid Roman numeral characters.');
  }

  let num = 0;
  let remaining = text;

  for (const { val, sym } of ROMAN_MAP) {
    while (remaining.startsWith(sym)) {
      num += val;
      remaining = remaining.slice(sym.length);
    }
