/**
 * Converts text to title case based on specific rules.
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') {
    return '';
  }

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  // Split by whitespace while preserving the whitespace structure
  // Using a regex with capturing group keeps the delimiters in the array
  const parts = text.split(/(\s+)/);

  const words = [];
  const wordIndices = [];

  // Identify words and their positions
  for (let i = 0; i < parts.length; i++) {
    if (!/^\s+$/.test(parts[i])) {
      words.push(parts[i]);
      wordIndices.push(i);
    }
  }

  if (words.length === 0) return text;

  const processWord = (word, isFirstOrLast) => {
    // Rule 1: Acronyms (all caps, length >= 2)
    if (/^[A-Z]{2,}$/.test(word)) {
      return word;
    }

    // Rule 2: Hyphenated words
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false)).join('-');
    }

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirstOrLast) {
      return lower;
    }

    // Rule 3: Capitalizing
    // Find the first letter index
    const firstLetterIndex = word.search(/[a-zA-Z]/);
    if (firstLetterIndex === -1) return word;

    return (
      word.slice(0, firstLetterIndex) +
      word[firstLetterIndex].toUpperCase() +
      word.slice(firstLetterIndex + 1).toLowerCase()
    );
  };

  // Apply rules to words
  for (let i = 0; i < words.length; i++) {
    const isFirstOrLast = (i === 0 || i === words.length - 1);
    parts[wordIndices[i]] = processWord(words[i], isFirstOrLast);
  }

  return parts.join('');
}
