/**
 * Parses a URL query string into an object with no prototype.
 * 
 * @param {string} query 
 * @returns {Object}
 */
export function parseQuery(query) {
  if (typeof query !== 'string') {
    throw new TypeError('Query must be a string');
  }

  const result = Object.create(null);
  const isArrayKey = Object.create(null);

  // Remove leading '?'
  if (query.startsWith('?')) {
    query = query.slice(1);
  }

  if (!query) return result;

  const pairs = query.split('&');

  for (const pair of pairs) {
    if (!pair) continue;

    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;

    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.substring(0, eqIndex);
      rawValue = pair.substring(eqIndex + 1);
    }

    const key = decode(rawKey);
    const value = decode(rawValue);

    let finalKey = key;
    let forceArray = false;

    if (key.endsWith('[]')) {
      finalKey = key.slice(0, -2);
      forceArray = true;
    }

    if (forceArray) {
      isArrayKey[finalKey] = true;
    }

    if (!(finalKey in result)) {
      result[finalKey] = forceArray ? [value] : value;
    } else {
      const existing = result[finalKey];
      if (Array.isArray(existing)) {
        existing.push(value);
      } else {
        result[finalKey] = [existing, value];
      }
    }
  }

  // Post-process: ensure keys marked with [] are always arrays
  for (const key in isArrayKey) {
    if (!Array.isArray(result[key])) {
      result[key] = [result[key]];
    }
  }

  return result;
}

/**
 * Decodes a string according to URL query rules:
 * + becomes space, then decodeURIComponent.
 */
function decode(str) {
  const plusReplaced = str.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(plusReplaced);
  } catch (e) {
    throw new RangeError('Malformed percent-escape');
  }
}
