/**
 * Parses a single line of CSV according to RFC 4180-like rules.
 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} if input is not a string
 * @throws {RangeError} if the CSV format is invalid
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const result = [];
  let i = 0;

  while (i <= line.length) {
    // Check if the field is quoted
    if (i < line.length && line[i] === '"') {
      let field = '';
      i++; // Skip opening quote
      let closed = false;

      while (i < line.length) {
        if (line[i] === '"') {
          if (line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) {
        throw new RangeError('Quoted field not closed');
      }

      // After a closing quote, we expect either a comma or end of string
      if (i < line.length && line[i] !== ',') {
        throw new RangeError('Invalid character after closing quote');
      }

      result.push(field);
      i++; // Skip comma
    } else {
      // Unquoted field
      let field = '';
      while (i < line.length && line[i] !== ',') {
        if (line[i] === '"') {
          throw new RangeError('Quote found inside unquoted field');
        }
        field += line[i];
        i++;
      }
      result.push(field);
      i++; // Skip comma
    }

    // If the line ends with a comma, we need to add one more empty field
    if (i === line.length && line[line.length - 1] === ',') {
      result.push('');
      break;
    }
  }

  return result;
}
