      groupKey = key(item, i);
    } else {
      // If item is null or undefined, item[key] would throw.
      // The requirement states: if string key is used on null/undefined, 
      // it goes to the undefined group.
      if (item === null || item === undefined) {
        groupKey = undefined;
      } else {
        groupKey = item[key];
      }
    }

    if (!map.has(groupKey)) {
      map.set(groupKey, []);
    }

    map.get(groupKey).push(item);
  }

  return map;
}
